    @SuppressWarnings({"unchecked", "rawtypes"})
    private static final java.util.HashMap<String, Integer>[] RESOLVERS = new java.util.HashMap[655];

    public static TokenArray lex(String input) {
        TokenArrayBuilder builder = new TokenArrayBuilder(input);
        int len = input.length();
        int pos = 0;
        while (pos < len) {
            int state = 0;
            int lastAcceptEnd = -1;
            int lastAcceptKind = -1;
            int cur = pos;
            while (cur < len) {
                int ch = input.charAt(cur);
                int next;
                if (ch >= 256) {
                    next = NON_ASCII_TRANSITIONS[state];
                } else {
                    next = TRANSITIONS[state * 256 + ch];
                }
                if (next < 0) break;
                state = next;
                cur++;
                int ak = ACCEPT_KIND[state];
                if (ak >= 0) {
                    lastAcceptEnd = cur;
                    lastAcceptKind = ak;
                }
            }
            if (lastAcceptEnd <= pos) {
                builder.append(TokenArray.KIND_WHITESPACE, pos, pos + 1);
                pos++;
                continue;
            }
            if ((lastAcceptKind == TokenArray.KIND_WHITESPACE
                 || lastAcceptKind == TokenArray.KIND_LINE_COMMENT
                 || lastAcceptKind == TokenArray.KIND_BLOCK_COMMENT)
                && lastAcceptEnd > pos + 1) {
                char c0 = input.charAt(pos);
                char c1 = input.charAt(pos + 1);
                if (c0 == '/') {
                    if (c1 == '/') {
                        if (lastAcceptEnd > pos + 2 && input.charAt(pos + 2) == '/') {
                            lastAcceptKind = TokenArray.KIND_DOC_LINE_COMMENT;
                        } else {
                            lastAcceptKind = TokenArray.KIND_LINE_COMMENT;
                        }
                    } else if (c1 == '*') {
                        boolean isDoc = lastAcceptEnd > pos + 2
                                        && input.charAt(pos + 2) == '*'
                                        && !(lastAcceptEnd == pos + 4 && input.charAt(pos + 3) == '/');
                        lastAcceptKind = isDoc ? TokenArray.KIND_DOC_BLOCK_COMMENT : TokenArray.KIND_BLOCK_COMMENT;
                    }
                }
            }
            builder.append(lastAcceptKind, pos, lastAcceptEnd);
            pos = lastAcceptEnd;
        }
        return builder.build(KIND_NAMES);
    }
